--
-- Name: calcular_comision(numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calcular_comision(p_monto numeric, p_tasa numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT ROUND(p_monto * p_tasa / 100.0, 2);
$$;


--
-- Name: fn_avance_estudiante(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_avance_estudiante(p_estudiante_id uuid, p_curso_id uuid) RETURNS TABLE(total_modulos bigint, total_lecciones bigint, estado_inscripcion text, certificado boolean, calificacion numeric)
    LANGUAGE sql STABLE
    AS $$
    SELECT
        COALESCE(mc.cnt, 0)                    AS total_modulos,
        COALESCE(lc.cnt, 0)                    AS total_lecciones,
        i.estado::text                         AS estado_inscripcion,
        COALESCE(i.certificado_obtenido, false) AS certificado,
        i.calificacion_final                   AS calificacion
    FROM (SELECT 1) AS dummy
    LEFT JOIN inscripciones i
           ON i.estudiante_id = p_estudiante_id
          AND i.curso_id      = p_curso_id
    LEFT JOIN LATERAL (
        SELECT COUNT(*) AS cnt FROM modulos WHERE curso_id = p_curso_id
    ) mc ON true
    LEFT JOIN LATERAL (
        SELECT COUNT(*) AS cnt
          FROM lecciones l
          JOIN modulos m ON m.id = l.modulo_id
         WHERE m.curso_id = p_curso_id
    ) lc ON true;
$$;


--
-- Name: fn_ingresos_instructor(smallint, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_ingresos_instructor(p_instructor_id smallint, p_desde date, p_hasta date) RETURNS TABLE(curso_id uuid, titulo character varying, total_inscripciones bigint, ingreso_bruto numeric, ingreso_neto numeric)
    LANGUAGE sql STABLE
    AS $$
    SELECT
        c.id,
        c.titulo,
        COUNT(i.id)                                                            AS total_inscripciones,
        COALESCE(SUM(i.monto_pagado), 0)                                       AS ingreso_bruto,
        COALESCE(SUM(i.monto_pagado * (1 - i.tasa_comision_aplicada / 100)), 0) AS ingreso_neto
      FROM cursos c
      LEFT JOIN inscripciones i
             ON i.curso_id = c.id
            AND i.fecha_inscripcion::date BETWEEN p_desde AND p_hasta
     WHERE c.instructor_id = p_instructor_id
     GROUP BY c.id, c.titulo
     ORDER BY ingreso_neto DESC;
$$;


--
-- Name: sp_emitir_certificado(uuid); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_emitir_certificado(IN p_inscripcion_id uuid)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado       text;
    v_permite_cert boolean;
    v_estudiante   uuid;
    v_codigo       varchar(100);
    v_curso_id     uuid;
    v_user_id      uuid;
BEGIN
    -- Validar inscripcion y curso
    SELECT i.estado::text, c.permite_certificado, i.estudiante_id, c.id
      INTO v_estado, v_permite_cert, v_estudiante, v_curso_id
      FROM inscripciones i
      JOIN cursos c ON c.id = i.curso_id
     WHERE i.id = p_inscripcion_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'La inscripcion % no existe', p_inscripcion_id;
    END IF;

    -- Solo inscripciones completadas
    IF v_estado <> 'completado' THEN
        RAISE EXCEPTION 'No se puede certificar: la inscripcion no esta completada (estado: %)', v_estado
            USING ERRCODE = 'check_violation';
    END IF;

    -- El curso debe permitir certificado
    IF NOT v_permite_cert THEN
        RAISE EXCEPTION 'El curso no otorga certificado'
            USING ERRCODE = 'check_violation';
    END IF;

    -- No duplicados
    IF EXISTS (SELECT 1 FROM certificados WHERE inscripcion_id = p_inscripcion_id) THEN
        RAISE EXCEPTION 'El certificado de esta inscripcion ya fue emitido'
            USING ERRCODE = 'unique_violation';
    END IF;

    -- Generar codigo unico
    v_codigo := 'CERT-' || upper(substr(replace(p_inscripcion_id::text, '-', ''), 1, 12));

    -- Emitir certificado
    VALUES (
        p_inscripcion_id,
        v_codigo,
        'https://edusphere.app/certificados/' || v_codigo
    );

    -- Resolver usuario_id del estudiante para auditoria
    SELECT e.usuario_id INTO v_user_id
      FROM estudiantes e
     WHERE e.id = v_estudiante;

    -- Auditoria
    SELECT
        v_user_id,
        tao.id,
        'certificados',
        p_inscripcion_id,
        jsonb_build_object(
            'codigo', v_codigo,
            'curso_id', v_curso_id,
            'estudiante_id', v_estudiante
        )
    FROM tipos_operacion_auditoria tao
    WHERE tao.nombre = 'emision_certificado';

    -- Reflejar emision en tablas relacionadas
    UPDATE inscripciones SET certificado_obtenido = true                 WHERE id = p_inscripcion_id;
    UPDATE estudiantes   SET total_certificados   = total_certificados + 1 WHERE id = v_estudiante;
END;
$$;


--
-- Name: sp_inscribir_estudiante(uuid, uuid, public.metodo_pago_e); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_inscribir_estudiante(IN p_usuario_id uuid, IN p_curso_id uuid, IN p_metodo_pago public.metodo_pago_e DEFAULT 'tarjeta'::public.metodo_pago_e)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_est_id        uuid;
    v_ins_id        uuid;
    v_estado_curso  text;
    v_precio        numeric(10,2);
    v_tasa          numeric(5,2) := 30.00;
    v_comision      numeric(10,2);
BEGIN
    -- Resolver estudiante_id desde usuario_id
    SELECT id INTO v_est_id FROM estudiantes WHERE usuario_id = p_usuario_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'El usuario % no tiene perfil de estudiante', p_usuario_id;
    END IF;

    -- Obtener estado y precio del curso
    SELECT c.estado::text, COALESCE(c.precio_descuento, c.precio)
      INTO v_estado_curso, v_precio
      FROM cursos c
     WHERE c.id = p_curso_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'El curso % no existe', p_curso_id;
    END IF;

    -- RN-02: solo cursos publicados
    IF v_estado_curso <> 'publicado' THEN
        RAISE EXCEPTION 'El curso no esta publicado (estado: %)', v_estado_curso
            USING ERRCODE = 'check_violation';
    END IF;

    -- RN-01: no duplicados
    IF EXISTS (
        SELECT 1 FROM inscripciones
         WHERE estudiante_id = v_est_id
           AND curso_id      = p_curso_id
    ) THEN
        RAISE EXCEPTION 'El estudiante ya esta inscrito en este curso'
            USING ERRCODE = 'unique_violation';
    END IF;

    -- RN-04: calcular comision usando la funcion escalar
    v_comision := calcular_comision(v_precio, v_tasa);

    -- Crear inscripcion
    VALUES (v_est_id, p_curso_id, v_precio, v_tasa)
    RETURNING id INTO v_ins_id;

    -- RN-03: registrar pago (snapshot del precio al momento de inscripcion)
    VALUES (
        v_ins_id,
        v_precio,
        p_metodo_pago,
        'ref-' || replace(gen_random_uuid()::text, '-', ''),
        'EduSphere Demo',
        'completado',
        jsonb_build_object(
            'curso', p_curso_id,
            'plataforma', 'EduSphere',
            'tasa', v_tasa,
            'comision', v_comision
        )
    );

    -- Auditoria: registro inmutable de la operacion
    SELECT
        p_usuario_id,
        tao.id,
        'inscripciones',
        v_ins_id,
        jsonb_build_object(
            'estudiante_id', v_est_id,
            'curso_id', p_curso_id,
            'monto', v_precio,
            'tasa', v_tasa,
            'comision', v_comision
        )
    FROM tipos_operacion_auditoria tao
    WHERE tao.nombre = 'inscripcion_curso';

    -- Actualizar contadores desnormalizados
    UPDATE cursos      SET total_estudiantes = total_estudiantes + 1 WHERE id = p_curso_id;
    UPDATE estudiantes SET total_cursos      = total_cursos + 1      WHERE id = v_est_id;
END;
$$;


