--
-- Name: vm_ingresos_mensuales; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.vm_ingresos_mensuales AS
 SELECT date_trunc('month'::text, p.fecha_pago) AS mes,
    cat.nombre AS categoria,
    count(DISTINCT i.id) AS total_inscripciones,
    sum(p.monto) AS ingresos_totales,
    round(avg(p.monto), 2) AS ticket_promedio
   FROM (((public.pagos p
     JOIN public.inscripciones i ON ((i.id = p.inscripcion_id)))
     JOIN public.cursos c ON ((c.id = i.curso_id)))
     JOIN public.categorias cat ON ((cat.id = c.categoria_id)))
  WHERE (p.estado = 'completado'::public.estado_pago_e)
  GROUP BY (date_trunc('month'::text, p.fecha_pago)), cat.nombre
  ORDER BY (date_trunc('month'::text, p.fecha_pago)) DESC, (sum(p.monto)) DESC
  WITH NO DATA;


--
-- Name: mv_ingresos_mensuales; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.mv_ingresos_mensuales AS
 SELECT mes,
    categoria,
    total_inscripciones,
    ingresos_totales,
    ticket_promedio
   FROM public.vm_ingresos_mensuales;


