CREATE TABLE public.usuarios (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    nombre character varying(200) NOT NULL,
    apellido character varying(200) NOT NULL,
    email character varying(255) NOT NULL,
    fecha_nacimiento date,
    rol public.rol_usuario NOT NULL,
    fecha_registro timestamp with time zone DEFAULT now() NOT NULL,
    fecha_modificacion timestamp with time zone DEFAULT now() NOT NULL,
    password_hash character varying(255) NOT NULL,
    telefono character varying(20),
    modificado_por uuid,
    CONSTRAINT chk_usuarios_email CHECK (((email)::text ~* '^[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}$'::text))
);


--
-- Name: vm_top_cursos_vendidos; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.vm_top_cursos_vendidos AS
 SELECT c.id,
    c.titulo,
    c.nivel,
    cat.nombre AS categoria,
    (((u.nombre)::text || ' '::text) || (u.apellido)::text) AS instructor,
    count(i.id) AS total_inscritos,
    sum(i.monto_pagado) AS ingresos_generados
   FROM ((((public.cursos c
     JOIN public.categorias cat ON ((cat.id = c.categoria_id)))
     JOIN public.instructores ins ON ((ins.id = c.instructor_id)))
     JOIN public.usuarios u ON ((u.id = ins.usuario_id)))
     JOIN public.inscripciones i ON ((i.curso_id = c.id)))
  WHERE (c.estado = 'publicado'::public.estado_curso_e)
  GROUP BY c.id, c.titulo, c.nivel, cat.nombre, u.nombre, u.apellido
  ORDER BY (count(i.id)) DESC
 LIMIT 10
  WITH NO DATA;


--
-- Name: mv_top_cursos_trimestre; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.mv_top_cursos_trimestre AS
 SELECT id,
    titulo,
    nivel,
    categoria,
    instructor,
    total_inscritos,
    ingresos_generados
   FROM public.vm_top_cursos_vendidos;


--
-- Name: preguntas; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.preguntas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    leccion_id uuid NOT NULL,
    texto text NOT NULL,
    tipo public.tipo_pregunta_e NOT NULL,
    opciones jsonb,
    respuesta_correcta text NOT NULL,
    puntos smallint DEFAULT 1 NOT NULL,
    orden smallint NOT NULL,
    fecha_creacion timestamp with time zone DEFAULT now() NOT NULL,
    fecha_modificacion timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_preguntas_orden CHECK ((orden > 0)),
    CONSTRAINT chk_preguntas_puntos CHECK ((puntos > 0))
);


