--
-- Name: vw_catalogo_cursos_publicados; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_catalogo_cursos_publicados AS
 SELECT c.id AS curso_id,
    c.titulo,
    c.slug,
    c.descripcion,
    c.nivel,
    c.idioma,
    c.precio,
    c.precio_descuento,
    c.duracion_horas,
    c.calificacion_promedio,
    c.total_estudiantes,
    c.imagen_portada_url,
    c.permite_certificado,
    c.fecha_publicacion,
    cat.nombre AS categoria,
    (((u.nombre)::text || ' '::text) || (u.apellido)::text) AS instructor
   FROM (((public.cursos c
     JOIN public.categorias cat ON ((cat.id = c.categoria_id)))
     JOIN public.instructores ins ON ((ins.id = c.instructor_id)))
     JOIN public.usuarios u ON ((u.id = ins.usuario_id)))
  WHERE (c.estado = 'publicado'::public.estado_curso_e);


--
-- Name: vw_cursos_estudiante; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_cursos_estudiante AS
 SELECT e.usuario_id AS estudiante_id,
    e.id AS estudiante_real_id,
    i.id AS inscripcion_id,
    i.estado AS estado_inscripcion,
    i.fecha_inscripcion,
    i.monto_pagado,
    i.calificacion_final,
    i.certificado_obtenido,
    c.id AS curso_id,
    c.titulo AS curso_titulo,
    c.slug AS curso_slug,
    c.nivel AS curso_nivel,
    c.duracion_horas,
    (((u.nombre)::text || ' '::text) || (u.apellido)::text) AS instructor,
    COALESCE(s.total_modulos, (0)::bigint) AS total_modulos,
    COALESCE(s.total_lecciones, (0)::bigint) AS total_lecciones
   FROM (((((public.estudiantes e
     JOIN public.inscripciones i ON ((i.estudiante_id = e.id)))
     JOIN public.cursos c ON ((c.id = i.curso_id)))
     JOIN public.instructores ins ON ((ins.id = c.instructor_id)))
     JOIN public.usuarios u ON ((u.id = ins.usuario_id)))
     LEFT JOIN LATERAL ( SELECT count(DISTINCT m.id) AS total_modulos,
            count(DISTINCT l.id) AS total_lecciones
           FROM (public.modulos m
             LEFT JOIN public.lecciones l ON ((l.modulo_id = m.id)))
          WHERE (m.curso_id = c.id)) s ON (true))
  WHERE (i.estado = ANY (ARRAY['activo'::public.estado_inscripcion_e, 'completado'::public.estado_inscripcion_e]));


--
-- Name: vw_tasa_finalizacion; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_tasa_finalizacion AS
 SELECT c.id AS curso_id,
    c.titulo,
    c.nivel,
    count(i.id) FILTER (WHERE (i.estado = 'completado'::public.estado_inscripcion_e)) AS completados,
    count(i.id) AS total_inscritos,
        CASE
            WHEN (count(i.id) > 0) THEN round((((count(i.id) FILTER (WHERE (i.estado = 'completado'::public.estado_inscripcion_e)))::numeric * 100.0) / (count(i.id))::numeric), 2)
            ELSE (0)::numeric
        END AS tasa_finalizacion
   FROM (public.cursos c
     LEFT JOIN public.inscripciones i ON ((i.curso_id = c.id)))
  WHERE (c.estado = 'publicado'::public.estado_curso_e)
  GROUP BY c.id, c.titulo, c.nivel
 HAVING (count(i.id) > 0)
  ORDER BY
        CASE
            WHEN (count(i.id) > 0) THEN round((((count(i.id) FILTER (WHERE (i.estado = 'completado'::public.estado_inscripcion_e)))::numeric * 100.0) / (count(i.id))::numeric), 2)
            ELSE (0)::numeric
        END DESC;


